use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let started = wall_clock::now().seconds;
        let date = format_date(started);
        RunInfo { date, started }
    }
}

/// Formats Unix seconds as `YYYY-MM-DD` (UTC), always exactly 10 characters.
/// Uses the civil-from-days algorithm (Howard Hinnant).
fn format_date(unix_seconds: u64) -> String {
    let days = (unix_seconds / 86_400) as i64;
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    if month <= 2 {
        year += 1;
    }
    // Keep the output a four-digit year so the `len(date) == 10` ensures holds.
    let year = year.clamp(0, 9_999);
    format!("{:04}-{:02}-{:02}", year, month, day)
}

export!(Node);
